SELECT rule.modification_suggestions modificationSuggestions, rule.alarm_level alarmLevel, rule.select_type selectType, model.table_name tableName, tech.column_name columnIdName, tech1.column_name columnName, tech2.column_name ruleColumnName, rule.customized_sql customizedSql, rule.rule_id ruleId, brule.rule_name ruleName, brule.rule_description ruleDescription, brule.english_name englishName FROM t_quality_verification_rules rule LEFT JOIN t_quality_basic_rules brule ON CONCAT(brule.id) = rule.rule_id LEFT JOIN t_meta_model model ON CONCAT(model.id) = rule.rel_meta_mode_id LEFT JOIN t_meta_model_tech tech ON CONCAT(tech.id)= rule.rel_id_meta_model_column_id LEFT JOIN t_meta_model_tech tech1 ON CONCAT(tech1.id) = rule.rel_name_meta_model_column_id LEFT JOIN t_meta_model_tech tech2 ON CONCAT(tech2.id) = rule.meta_model_column_id
and rule.meta_mode_id = #{modeId}
AND rule.model_version = #{modeVersion}
AND rule.id = #{vRuleId}
AND tech2.column_name = #{attribute}

SELECT distinct res.rule_category ruleCategory, res.verification_rule_id verificationRuleId, res.error_column_name_cn errorColumnNameCn, res.error_column_name errorColumnName, res.resource_type resourceType, res.problem_type problemType, res.rule_description ruleDescription, res.modification_suggestions probmodificationSuggestionslemType FROM t_quality_verification_result res LEFT JOIN t_quality_verification_rules rule ON CONCAT(rule.id) = res.verification_rule_id
and res.error_id = #{errorId}
AND rule.model_version = #{modeVersion}

SELECT distinct rule.modification_suggestions modificationSuggestions, tech.column_name errorColumnName, tech.column_name_cn errorColumnNameCn, rule.rule_id verificationRuleId, brule.rule_name problemType, rule.rule_description ruleDescription, '0' ruleCategory, '通信站' resourceType FROM t_quality_verification_rules rule LEFT JOIN t_quality_basic_rules brule ON brule.id = rule.rule_id LEFT JOIN t_meta_model_tech tech ON tech.id = rule.meta_model_column_id
and rule.state = '0'
and rule.meta_mode_id = #{modeId}
AND rule.model_version = #{modeVersion}

SELECT rule.id id , tech.column_name columnName, tech.column_name_cn columnNameCn, rule.rule_description ruleDescription, ( CASE WHEN rule.alarm_level = '0' THEN '告警' WHEN rule.alarm_level = '1' THEN '提醒' WHEN rule.alarm_level = '2' THEN '通用校验' END ) alarmLevel, rule.modification_suggestions modificationSuggestions, brule.rule_name ruleName, rule.customized_sql customizedSql, ( CASE WHEN rule.state = '0' THEN '启动' WHEN rule.state = '1' THEN '禁用' END ) state, rule.superior_unit_id superiorUnitId, '0' ruleCategory FROM t_quality_verification_rules rule LEFT JOIN t_meta_model_tech tech ON tech.id = rule.meta_model_column_id LEFT JOIN t_quality_basic_rules brule ON brule.id = rule.rule_id
and rule.meta_model_id = #{modeId}
UNION SELECT rule.id id, model.table_name columnName, model.table_name_cn columnNameCn, rule.rule_description ruleDescription, ( CASE WHEN rule.alarm_level = '0' THEN '告警' WHEN rule.alarm_level = '1' THEN '提醒' WHEN rule.alarm_level = '2' THEN '通用校验' END ) alarmLevel, rule.modification_suggestions modificationSuggestions, brule.rule_name ruleName, rule.use_defined_ver_sql customizedSql, ( CASE WHEN rule.state = '0' THEN '启动' WHEN rule.state = '1' THEN '禁用' END ) state, rule.superior_unit_id superiorUnitId, '1' ruleCategory FROM t_quality_ass_rule_verification rule LEFT JOIN t_meta_model model ON model.id = rule.meta_mode_id LEFT JOIN t_quality_association_rules brule ON brule.id = rule.verification_rule_id
and rule.meta_model_id = #{modeId}

select rule.id ruleId, vrule.id vruleId, vrule.meta_mode_id modelId, rule.rule_name ruleName, rule.english_name englishName, model.table_name tableName, model1.table_name rtableName, tech.column_name columnName, tech.column_name_cn columnNameCn, tech.column_type columnType, tech1.column_name rcolumnName, tech1.column_name_cn rcolumnNameCn, tech1.column_type rcolumnType, tech2.column_name rcolumnName1, tech2.column_name_cn rcolumnNameCn1, tech2.column_type rcolumnType1, vrule.modification_suggestions modificationSuggestions, vrule.rule_description ruleDescription, vrule.select_type selectType, vrule.symbol symbol, vrule.param param, vrule.customized_sql customizedSql FROM t_quality_verification_rules vrule LEFT JOIN t_quality_basic_rules rule ON vrule.rule_id = CONCAT( rule.id ) LEFT JOIN t_meta_model model ON CONCAT( model.id ) = vrule.meta_mode_id LEFT JOIN t_meta_model_tech tech ON CONCAT( tech.id ) = vrule.meta_model_column_id LEFT JOIN t_meta_model model1 ON CONCAT( model1.id ) = vrule.rel_meta_mode_id LEFT JOIN t_meta_model_tech tech1 ON CONCAT( tech1.id ) = vrule.rel_id_meta_model_column_id LEFT JOIN t_meta_model_tech tech2 ON CONCAT( tech2.id ) = vrule.rel_name_meta_model_column_id
and vrule.state = '0'
and rule.id =#{ruleId}
and vrule.meta_mode_id =#{modelId}
and vrule.meta_model_column_id =#{commId}



    and t.column_name like concat('%', #{columnName}, '%')

    and t.column_name_cn like concat('%',
        #{columnNameCn},
        '%')

    and t.column_type like #concat('%', #{columnType}, '%')

    and t.column_length = #{columnLength}
     and meta_mode_id = #{metaModeId}
     and meta_model_column_id = #{metaModelColumnId}
     and rule_id = #{ruleId}
     and b.rule_name= #{ruleId}
     and alarm_level = #{alarmLevel}
     and rule_description = #{ruleDescription}
     and modification_suggestions = #{modificationSuggestions}
     and state = #{state}
     and superior_unit_id = #{superiorUnitId}
     and select_type = #{selectType}
     and symbol = #{symbol}
     and param = #{param}
     and rel_meta_mode_id = #{relMetaModeId}
     and rel_id_meta_model_column_id = #{relIdMetaModelColumnId}
     and rel_name_meta_model_column_id = #{relNameMetaModelColumnId}
     and customized_sql = #{customizedSql}
     and v.model_version = #{modelVersion}

ORDER BY sort_num asc,t.create_date asc

